              status={decisionStatus}
              onApprove={() => setApproved(true)}
            />
          ) : null}
          <MessageComposer
            value={draft}
            onChange={setDraft}
            onSend={sendMessage}
          />
        </div>
      </div>
      <Suspense fallback={null}>
        <CallDetailDialog />
