"use client"

import { Suspense, useEffect, useState } from "react"
import {
  Conversation,
  ConversationContent,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation"
import { Message, MessageContent } from "@/components/ai-elements/message"
import { AssistantTurn } from "@/components/cockpit/assistant-turn"
import { CallDetailDialog } from "@/components/cockpit/call-detail-dialog"
import { CandidatePanel } from "@/components/cockpit/candidate-panel"
import { CockpitShell } from "@/components/cockpit/cockpit-shell"
import { DecisionBar, type DecisionStatus } from "@/components/cockpit/decision-bar"
import { DotLoader } from "@/components/cockpit/dot-loader"
import { IncidentHeader } from "@/components/cockpit/incident-header"
import { IncidentRequestMessage } from "@/components/cockpit/incident-request-message"
import { MessageComposer } from "@/components/cockpit/message-composer"
import { SCRIPT, TICK_MS } from "@/lib/case-001"

export function CockpitChat() {
  const [visible, setVisible] = useState(0)
  const [approved, setApproved] = useState(false)
  const [candidatesOpen, setCandidatesOpen] = useState(true)
  const [draft, setDraft] = useState("")
  const [messages, setMessages] = useState<string[]>([])
  const running = visible < SCRIPT.length

  useEffect(() => {
    if (!running) return

    const id = window.setInterval(() => {
      setVisible((count) => Math.min(count + 1, SCRIPT.length))
    }, TICK_MS)
    return () => window.clearInterval(id)
  }, [running])

  const latestStep = SCRIPT[Math.min(visible, SCRIPT.length) - 1]
  const currentStep =
    visible === 0
      ? "Launching"
      : latestStep.kind === "decision"
        ? "Decision ready"
        : latestStep.stepName
  const checksPassed = isStepVisible("tests", visible)
  const decisionExists = isStepVisible("strategy", visible)
  const decisionStatus: DecisionStatus = approved
    ? "approved"
    : !running && !checksPassed
      ? "on hold"
      : checksPassed
        ? "needs human review"
        : "evaluating"

  function replay() {
    const skipTicks = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    setVisible(skipTicks ? SCRIPT.length : 0)
    setApproved(false)
  }

  function sendMessage(message: string) {
    const text = message.trim()
    if (!text) return

    setMessages((current) => [...current, text])
    setDraft("")
  }

  return (
    <CockpitShell
      rightSidebar={
        candidatesOpen ? (
          <CandidatePanel
            visible={visible}
            onClose={() => setCandidatesOpen(false)}
          />
        ) : undefined
      }
    >
      <div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)_auto] overflow-hidden">
        <IncidentHeader
          visible={visible}
          approved={approved}
          running={running}
          onReplay={replay}
          showOpenCandidates={!candidatesOpen}
          onOpenCandidates={() => setCandidatesOpen(true)}
        />
        <Conversation className="min-h-0">
          <ConversationContent
            className="mx-auto w-full max-w-[50vw] gap-4 px-4 py-4"
            scrollClassName="chat-scrollbar overflow-x-hidden overflow-y-auto"
          >
            <IncidentRequestMessage />
            {SCRIPT.slice(0, visible).map((step, index) => (
              <AssistantTurn
                key={step.id}
                step={step}
                latest={index === visible - 1 && running}
              />
            ))}
            {running ? (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <DotLoader />
                <span>{currentStep}</span>
              </div>
            ) : null}
            {messages.map((message, index) => (
              <Message key={`${index}-${message}`} from="user">
                <MessageContent>
                  <p>{message}</p>
                </MessageContent>
              </Message>
            ))}
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>
        <div className="shrink-0 bg-background">
          {decisionExists ? (
            <DecisionBar
              checksPassed={checksPassed}
              status={decisionStatus}
              onApprove={() => setApproved(true)}
            />
          ) : null}
          <MessageComposer
            value={draft}
            onChange={setDraft}
            onSend={sendMessage}
          />
        </div>
      </div>
      <Suspense fallback={null}>
        <CallDetailDialog />
      </Suspense>
    </CockpitShell>
  )
}

function isStepVisible(stepId: string, visible: number): boolean {
  const index = SCRIPT.findIndex((step) => step.id === stepId)
  return index >= 0 && visible > index
}

import { ArrowUpIcon } from "@/components/icons"
import {
  PromptInput,
  PromptInputBody,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
} from "@/components/ai-elements/prompt-input"

type MessageComposerProps = {
  value: string
  onChange: (value: string) => void
  onSend: (value: string) => void
}

export function MessageComposer({
  value,
  onChange,
  onSend,
}: MessageComposerProps) {
  return (
    <div className="mx-auto w-full max-w-[50vw] px-4 py-3">
      <PromptInput
        className="w-full bg-card [&_[data-slot=input-group]]:border-border/70"
        onSubmit={({ text }) => onSend(text)}
      >
        <PromptInputBody>
          <PromptInputTextarea
            aria-label="Message SupplyOS"
            placeholder="Message SupplyOS"
            value={value}
            onChange={(event) => onChange(event.currentTarget.value)}
          />
        </PromptInputBody>
        <PromptInputFooter>
          <PromptInputTools />
          <PromptInputSubmit disabled={!value.trim()} status="ready">
            <ArrowUpIcon aria-hidden="true" />
          </PromptInputSubmit>
        </PromptInputFooter>
      </PromptInput>
    </div>
  )
}

import {
  Message,
  MessageContent,
  MessageResponse,
} from "@/components/ai-elements/message"
import { Task, TaskContent, TaskItem, TaskTrigger } from "@/components/ai-elements/task"
import { Tool, ToolContent, ToolHeader, ToolOutput } from "@/components/ai-elements/tool"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { CANDIDATES, type ScriptStep } from "@/lib/case-001"

export function AssistantTurn({
  step,
  latest,
}: {
  step: ScriptStep
  latest: boolean
}) {
  return (
    <Message from="assistant" className="max-w-full">
      <MessageContent className="w-full max-w-full">
        <MessageResponse>
          {step.kind === "decision"
            ? "Decision ready for human review."
            : step.summary}
        </MessageResponse>
        {step.method && step.path ? (
          <Tool defaultOpen={false} className="mb-0">
            <ToolHeader
              type={`tool-${step.id}`}
              state={latest ? "input-available" : "output-available"}
              title={`${step.method} ${step.path}`}
            />
            <ToolContent>
              <ToolOutput
                output={<p className="p-3 text-pretty">{step.detail}</p>}
                errorText={undefined}
              />
            </ToolContent>
          </Tool>
        ) : null}
        <StepExtras step={step} />
      </MessageContent>
    </Message>
  )
}

function StepExtras({ step }: { step: ScriptStep }) {
  if (step.kind === "outreach") return <OutreachTasks />

  if (step.kind === "policy") {
    return (
      <Alert variant="destructive">
        <AlertTitle>Shenzhen Bearing Co rejected</AlertTitle>
        <AlertDescription>
          Rule <span className="font-mono">blocked_origin_country</span>. No
          Outreach Task.
        </AlertDescription>
      </Alert>
    )
  }

  if (step.kind === "deltas") {
    return (
      <p className="text-sm text-muted-foreground">
        Munich Motion Claim is{" "}
        <Badge variant="destructive">in_stock_allocated</Badge> — that stock is
        not ours.
      </p>
    )
  }

  if (step.kind === "decision") {
    return (
      <p className="text-sm text-muted-foreground">
        Winning Strategy: split 20% SKF air + 80% FAG sea. Required checks
        passed.
      </p>
    )
  }

  return null
}

function OutreachTasks() {
  const candidates = CANDIDATES.filter(
    (candidate) => candidate.compliance === "passed"
  )

  return (
    <Task defaultOpen>
      <TaskTrigger title="Outreach Tasks · 4 parallel" />
      <TaskContent className="[&>div]:mt-2 [&>div]:grid [&>div]:gap-2 [&>div]:border-l-0 [&>div]:pl-0 sm:[&>div]:grid-cols-2">
        {candidates.map((candidate) => (
          <TaskItem
            key={candidate.name}
            className="flex min-w-0 items-center justify-between gap-2 rounded-md border border-border px-2.5 py-2"
          >
            <span className="min-w-0">
              <span className="block truncate text-foreground">
                {candidate.name}
              </span>
              <span className="font-mono text-xs">{candidate.phone}</span>
            </span>
            <Badge variant="secondary">calling</Badge>
          </TaskItem>
        ))}
      </TaskContent>
    </Task>
  )
}

import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { SCRIPT } from "@/lib/case-001"
import { cn } from "@/lib/utils"

type RunStageState = "complete" | "active" | "pending"

const RUN_STAGES = [
  { label: "Incident", afterId: null },
  { label: "Candidates", afterId: "suppliers" },
  { label: "Outreach Tasks", afterId: "outreach" },
  { label: "Claims", afterId: "claims" },
  { label: "Decision", afterId: "strategy" },
] as const

const PEBBLE_CLASS: Record<RunStageState, string> = {
  complete: "bg-primary",
  active: "bg-foreground ring-1 ring-background/40",
  pending: "bg-muted-foreground/40",
}

export function RunStatusButton({
  visible,
  approved,
}: {
  visible: number
  approved: boolean
}) {
  const states = getRunStageStates(visible, approved)
  const activeIndex = states.findIndex((state) => state === "active")
  const currentIndex = activeIndex === -1 ? RUN_STAGES.length - 1 : activeIndex
  const currentStage = RUN_STAGES[currentIndex]

  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="bg-transparent px-2 text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:bg-muted dark:hover:bg-muted"
            aria-label={`Sourcing run status: ${currentStage.label}`}
          >
            <span
              aria-hidden="true"
              className={cn("size-2 rounded-full", PEBBLE_CLASS[states[currentIndex]])}
            />
            {currentStage.label}
          </Button>
        }
      />
      <TooltipContent
        side="bottom"
        align="end"
        sideOffset={6}
        className="min-w-44 flex-col items-stretch gap-0 px-3 py-3"
      >
        <ol aria-label="Sourcing run stages">
          {RUN_STAGES.map((stage, index) => (
            <RunStage key={stage.label} index={index} state={states[index]} />
          ))}
        </ol>
      </TooltipContent>
    </Tooltip>
  )
}

function RunStage({ index, state }: { index: number; state: RunStageState }) {
  return (
    <li
      aria-current={state === "active" ? "step" : undefined}
      className="relative flex gap-3 pb-3 last:pb-0"
    >
      <span
        aria-hidden="true"
        className={cn(
          "relative z-10 mt-0.5 size-2 shrink-0 rounded-full",
          PEBBLE_CLASS[state]
        )}
      />
      {index < RUN_STAGES.length - 1 ? (
        <span
          aria-hidden="true"
          className="absolute top-2 bottom-0 left-[3.5px] w-px bg-border"
        />
      ) : null}
      <span
        className={cn(
          "leading-none",
          state === "pending" && "text-muted-foreground"
        )}
      >
        {RUN_STAGES[index].label}
      </span>
    </li>
  )
}

function getRunStageStates(visible: number, approved: boolean): RunStageState[] {
  const completed = RUN_STAGES.map((stage) => {
    if (stage.label === "Decision") return approved
    if (stage.afterId === null) return true
    const stepIndex = SCRIPT.findIndex((step) => step.id === stage.afterId)
    return stepIndex >= 0 && visible > stepIndex
  })
  const activeIndex = completed.findIndex((complete) => !complete)

  return completed.map((complete, index) => {
    if (complete) return "complete"
    return index === activeIndex ? "active" : "pending"
  })
}

