}

function LifecycleBadge({ candidate, state }: { candidate: Candidate; state: CandidateState }) {
  if (state.policyComplete && candidate.compliance === "failed") return <Badge variant="destructive">rejected</Badge>
  if (state.claimsComplete) return <Badge variant="secondary">Claim filed</Badge>
  if (state.outreachStarted) return <Badge variant="outline">outreach</Badge>
  if (state.policyComplete) return <Badge variant="secondary">passed</Badge>
  return <Badge variant="outline">matched</Badge>
}

function RejectedCandidate({ candidate }: { candidate: Candidate }) {
