}

type ResultKind = "empty" | "call" | "compare" | "decision"

function resultKindFor(steps: ScriptStep[]): ResultKind {
  const kinds = new Set(steps.map((step) => step.kind))
  if (kinds.has("decision")) {
    return "decision"
  }
  if (kinds.has("deltas") || kinds.has("strategy") || kinds.has("tests")) {
    return "compare"
  }
  if (kinds.has("outreach") || kinds.has("claims")) {
    return "call"
  }
  return "empty"
}

function stockBadgeVariant(
  status: StockStatus
): "secondary" | "destructive" | "outline" {
  if (status === "in_stock_allocated" || status === "unavailable") {
    return "destructive"
  }
  if (status === "free_in_stock") {
    return "secondary"
  }
  return "outline"
}

export function paneForVisible(visible: number): WorkingTab {
  const kind = resultKindFor(SCRIPT.slice(0, visible))
  return kind === "empty" ? "files" : "results"
}

"use client"

import { useEffect } from "react"
import { PrototypeSwitcher } from "@/components/prototype/prototype-switcher"
import {
  VARIANTS,
  type VariantKey,
} from "@/components/prototype/website-prototype-config"
import { VARIANT_COMPONENTS } from "@/components/prototype/website-prototype-variants"

export function WebsitePrototype({
  initialVariant,
}: {
  initialVariant?: string
}) {
  const normalized = initialVariant?.toUpperCase()
  const currentKey: VariantKey = isVariantKey(normalized) ? normalized : "A"
  const currentIndex = VARIANTS.findIndex((variant) => variant.key === currentKey)
  const previousKey = VARIANTS[(currentIndex - 1 + VARIANTS.length) % VARIANTS.length].key
  const nextKey = VARIANTS[(currentIndex + 1) % VARIANTS.length].key

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null
      const isEditing =
        target?.tagName === "INPUT" ||
        target?.tagName === "TEXTAREA" ||
        target?.isContentEditable

      if (isEditing) return
      if (event.key === "ArrowLeft") {
        window.location.assign(`/prototype/website?variant=${previousKey}`)
      }
      if (event.key === "ArrowRight") {
        window.location.assign(`/prototype/website?variant=${nextKey}`)
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [nextKey, previousKey])

  const CurrentVariant = VARIANT_COMPONENTS[currentKey]
  const currentVariant = VARIANTS[currentIndex]

  return (
    <>
      <CurrentVariant />
      <PrototypeSwitcher
        currentIndex={currentIndex}
        label={`${currentVariant.key} (${currentVariant.label})`}
        total={VARIANTS.length}
        previousHref={`/prototype/website?variant=${previousKey}`}
        nextHref={`/prototype/website?variant=${nextKey}`}
      />
    </>
  )
}

function isVariantKey(value: string | undefined): value is VariantKey {
  return VARIANTS.some((variant) => variant.key === value)
}

